//! Independent per-row oracle shared by the integration suites.
//!
//! This module deliberately uses *nothing* from the bitmap engine
//! (`bits`, `trivalent`, `index`, `eval`): the reference answers are
//! produced by an independent, per-row scalar implementation of SQL
//! three-valued logic. The only library items reused are the data
//! definitions (predicate AST, typed scalars, table data access) — the
//! *computation* being verified (bitmap algebra, universe handling,
//! deletion versioning) is re-implemented here from scratch.
//!
//! Verdicts are therefore not generated by the implementation under test.

use std::collections::HashMap;

use bitindex3vl::predicate::Predicate;
use bitindex3vl::scalar::Scalar;
use bitindex3vl::table::Table;

/// Oracle tri-state. Mirrors SQL TRUE/FALSE/UNKNOWN without touching
/// `bitindex3vl::trivalent`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum O {
    T,
    F,
    U,
}

impl O {
    /// Kleene NOT, written out independently.
    pub fn not(self) -> O {
        match self {
            O::T => O::F,
            O::F => O::T,
            O::U => O::U,
        }
    }

    /// Kleene AND, written out independently.
    pub fn and(self, rhs: O) -> O {
        match (self, rhs) {
            (O::F, _) | (_, O::F) => O::F,
            (O::T, O::T) => O::T,
            _ => O::U,
        }
    }

    /// Kleene OR, written out independently.
    pub fn or(self, rhs: O) -> O {
        match (self, rhs) {
            (O::T, _) | (_, O::T) => O::T,
            (O::F, O::F) => O::F,
            _ => O::U,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            O::T => "TRUE",
            O::F => "FALSE",
            O::U => "UNKNOWN",
        }
    }
}

/// Per-row, per-cell recursive evaluation of a predicate. NULL propagates
/// to UNKNOWN at the leaf; logical nodes use the Kleene tables above.
pub fn oracle_row(pred: &Predicate, cell: &dyn Fn(&str) -> Option<&Scalar>) -> O {
    match pred {
        Predicate::Compare { column, op, value } => match cell(column) {
            // SQL: any comparison against NULL is UNKNOWN.
            None => O::U,
            Some(v) => {
                let hit = op
                    .compare(v, value)
                    .expect("oracle comparisons are type-correct by construction");
                if hit {
                    O::T
                } else {
                    O::F
                }
            }
        },
        Predicate::IsNull { column } => {
            if cell(column).is_none() {
                O::T
            } else {
                O::F
            }
        }
        Predicate::And(children) => {
            let mut acc = O::T;
            for c in children {
                acc = acc.and(oracle_row(c, cell));
            }
            acc
        }
        Predicate::Or(children) => {
            let mut acc = O::F;
            for c in children {
                acc = acc.or(oracle_row(c, cell));
            }
            acc
        }
        Predicate::Not(child) => oracle_row(child, cell).not(),
    }
}

/// Live-row vector as of `version`, recomputed here directly from the
/// delete log (not via `Table::universe_at`).
pub fn oracle_live_rows(table: &Table, version: u64) -> Vec<bool> {
    let mut live = vec![true; table.row_count()];
    for event in table.delete_log() {
        assert!(event.version > 0, "delete events must carry positive versions");
        if event.version <= version {
            for &row in &event.rows {
                assert!(row < table.row_count(), "delete log row out of range");
                live[row] = false;
            }
        }
    }
    live
}

/// Full oracle partition: one entry per physical row; `None` means the row
/// is outside the universe (deleted as of `version`).
pub fn oracle_partition(table: &Table, pred: &Predicate, version: u64) -> Vec<Option<O>> {
    let live = oracle_live_rows(table, version);
    let mut columns: HashMap<String, Vec<Option<Scalar>>> = HashMap::new();
    for (ci, col) in table.schema().columns.iter().enumerate() {
        let cells = table.column_cells(ci).expect("column materializes");
        columns.insert(col.name.clone(), cells);
    }
    (0..table.row_count())
        .map(|row| {
            if !live[row] {
                return None;
            }
            let columns = &columns;
            let get = move |name: &str| -> Option<&Scalar> {
                columns
                    .get(name)
                    .unwrap_or_else(|| panic!("oracle: unknown column {name:?}"))[row]
                    .as_ref()
            };
            Some(oracle_row(pred, &get))
        })
        .collect()
}

/// Deterministic run id for test logs so every line can be tied back to
/// the case that produced it.
pub fn case_run_id(case: &str, strategy: &str, version: u64) -> String {
    format!("test://{case}/{strategy}/v{version}")
}
